	"CommonPrayers/TheotokionNone": {
		"text": "Thou who for our sake wast born of a Virgin, and didst suffer crucifixion, O good One, and didst\r\ndespoil death through Death, and as God didst reveal Resurrection; despise not those whom Thou\r\nhast created with Thine own hand; show forth Thy love for mankind, O merciful one; accept the\r\nintercession of Thy Mother, the Theotokos, for us; and save Thy despairing people, O our Savior.",
		"header": "Theotakion in the Eighth Tone"
	},
	"CommonPrayers/TheotokionPr1": {
		"text": "My steps do Thou direct according to thy saying, and let no iniquity have dominion over me."
	},
	"CommonPrayers/TheotokionPr2": {
		"text": "Deliver me from the false accusations of men, and I will keep Thy commandments."
	},
	"CommonPrayers/TheotokionPr3": {
		"text": "Make Thy face to shine upon Thy servant, and teach me Thy statutes."
	},
	"CommonPrayers/TheotokionPr4": {
		"text": " Let my mouth be filled with Thy praise, that I may hymn Thy glory and Thy majesty all the day long."
	},
	"CommonPrayers/TheotokionPrimes": {
		"text": "What shall we call thee, O thou who art full of grace? Heaven, for from thee hast dawned forth the Sun of Righteousness. Paradise, for from thee bath blossomed forth the flower of immortality. Virgin, for thou hast remained incorrupt. Pure Mother, for thou hast held in thy holy embrace the Son, the God of all. Do thou entreat Him to save our souls.",
		"header": "Theotakion"
	},
	"CommonPrayers/TheotokionSext": {
		"text": "For verily, we have no favor for the multitude of our sins. Therefore, O virgin Theotokos, plead\r\nwith Him that was born of thee; for the pleadings of the Mother are very effective in seeking the\r\nfavor of the Master. Turn thou not away, therefore, from the pleadings of sinners, O most\r\nvenerable one; for He Who was willing to suffer for our sins is merciful and able to save us.",
		"header": "Theotakion"
	},
	"CommonPrayers/TheotokionTerce": {
		"text": "Thou art the true vine, O Theotokos, bearing the Fruit of life. Thee do we implore. Wherefore, O\r\nLady, intercede thou together with the Apostles and the saints, for the salvation of our souls.",
		"header": "Theotakion"
	},
	"CommonPrayers/ThriceHoly": {
		"text": "Holy God, Holy Mighty, Holy Immortal, have mercy on us."
	},
	"CommonPrayers/ThroughPrayers": {
		"text": "Through the prayers of our holy Fathers, Lord Jesus Christ our God, have mercy on us."
	},
	"CommonPrayers/TroparProph3": {
		"text": "Thou wast struck on the face for the sake of mankind, yet wast not moved to anger; deliver our life from corruption, O Lord, and save us.",
		"header": "Troparion of the Prophecy"
	},
	"CommonPrayers/VersTyp": {
		"text": "Come ye before Him and be lighted, and let not your faces be ashamed.",
		"header": ""
	},
